#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    string p;
    cin >> p;

    // prefix[i][c] = quantidade da letra c nos primeiros i caracteres
    vector<array<int, 26>> pre(n + 1);
    pre[0].fill(0);
    for (int i = 0; i < n; ++i) {
        pre[i + 1] = pre[i];
        pre[i + 1][p[i] - 'a']++;
    }

    // Tenta cada comprimento candidato L (raiz), em ordem crescente,
    // tal que L divide n e sobram pelo menos 2 blocos.
    for (int L = 1; 2 * L <= n; ++L) {
        if (n % L != 0) continue;

        const array<int, 26>& base = pre[L]; // contagens do bloco 0
        int k = n / L;                       // numero de blocos
        bool ok = true;

        for (int j = 1; j < k && ok; ++j) {
            const array<int, 26>& hi = pre[(j + 1) * L];
            const array<int, 26>& lo = pre[j * L];
            for (int c = 0; c < 26; ++c) {
                if (hi[c] - lo[c] != base[c]) { ok = false; break; }
            }
        }

        if (ok) {
            cout << p.substr(0, L) << "\n";
            return 0;
        }
    }

    cout << "*\n";
    return 0;
}
